def _un(x): return x .replace('~', '.') .replace('^', '/')
def _rs(s, h, t, v): h, t, v = _un(h), _un(t), _un(v); i = s .index(h); j = len(s) if t == '' else s .index(t, i + len(h)); return s[:i] + v + s[j:]
def _ap(od, fn, mk, ps): p = od .joinpath(fn + '.' + 'dart'); s = p .read_text('utf-8'); ok = _un(mk) not in s; p .write_text(functools .reduce(lambda c, x: _rs(c, x[0], x[1], x[2]), ps, s), 'utf-8') if ok else None
